import inspect
from typing import Callable, Any, Type
from fastapi.dependencies.utils import get_typed_return_annotation

# Mock implementation of get_typed_annotation for testing purposes, 
# as we are testing the wrapper logic in get_typed_return_annotation
def mock_get_typed_annotation(annotation: Any, globalns: dict) -> Any:
