# Temporarily patch the dependency for testing the wrapper logic
import fastapi.dependencies.utils as utils
utils.get_typed_annotation = mock_get_typed_annotation

def test_get_typed_return_annotation():
    print("--- Running tests for get_typed_return_annotation ---")

    # Case 1: No annotation (inspect.Signature.empty)
    def no_annotation():
        pass

    sig_empty = inspect.signature(no_annotation)
    annotation_empty = sig_empty.return_annotation
    result_empty = get_typed_return_annotation(no_annotation)
    assert result_empty is None, f"Test 1 Failed: Expected None, got {result_empty}"
    print("Test 1 (No annotation) Passed.")

    # Case 2: Annotation is None (object)
    def annotation_none():
        pass
    annotation_none_obj = None

    # We need a callable that reports None as return annotation
    def callable_none_obj():
        pass

    # Manually setting the return annotation for testing purposes
    sig_none_obj = inspect.signature(callable_none_obj)
    sig_none_obj.return_annotation = annotation_none_obj

    # Since we cannot easily modify the signature of an existing function, 
    # we simulate the input to get_typed_return_annotation

    # Let's create a mock callable that returns the desired annotation
    class MockCallable:
        def __call__(self):
            pass
        @property
        def __signature__(self):
            return inspect.Signature(return_annotation=annotation_none_obj)

    result_none_obj = get_typed_return_annotation(MockCallable())
    assert result_none_obj is None, f"Test 2 Failed: Expected None, got {result_none_obj}"
    print("Test 2 (Annotation is None object) Passed.")

    # Case 3: Annotation is string "None"
    class MockCallableStr:
        def __call__(self):
            pass
        @property
        def __signature__(self):
            return inspect.Signature(return_annotation="None")

    result_none_str = get_typed_return_annotation(MockCallableStr())
    assert result_none_str is None, f"Test 3 Failed: Expected None, got {result_none_str}"
    print("Test 3 (Annotation is string \"None\") Passed.")

    # Case 4: Annotation is type(None)
    class MockCallableType:
        def __call__(self):
            pass
        @property
        def __signature__(self):
            return inspect.Signature(return_annotation=type(None))

    result_type_none = get_typed_return_annotation(MockCallableType())
    assert result_type_none is None, f"Test 4 Failed: Expected None, got {result_type_none}"
    print("Test 4 (Annotation is type(None)) Passed.")

    # Case 5: Annotation is int (should pass through)
    class MockCallableInt:
        def __call__(self):
            pass
        @property
        def __signature__(self):
            return inspect.Signature(return_annotation=int)

    result_int = get_typed_return_annotation(MockCallableInt())
    assert result_int == int, f"Test 5 Failed: Expected int, got {result_int}"
    print("Test 5 (Annotation is int) Passed.")

test_get_typed_return_annotation()
